import java.util.*;

class Point2D {
    protected int x;
    protected int y;

    public Point2D() {
        this.x = 0;
        this.y = 0;
    }

    public void setValue(int a, int b) {
        this.x = a;
        this.y = b;
    }

    @Override
    public String toString() {
        return x + "@" + y;
    }
}

class Point3D extends Point2D {
    private int z;

    public Point3D() {
        super();
        this.z = 0;
    }

    @Override
    public void setValue(int a, int b) {
        super.setValue(a, b);
        this.z = a + b;
    }

    @Override
    public String toString() {
        return super.toString() + "@" + z;
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int a = sc.nextInt();
        int b = sc.nextInt();

        Point3D p = new Point3D();
        p.setValue(a, b);
        System.out.println(p.toString());
    }
}

